import { promises as fs } from "node:fs";
import * as path from "node:path";
import matter from "gray-matter";
import type { ParsedNote } from "../../../types.js";
import { extractWikilinks, extractFrontmatterWikilinks } from "./wikilinks.js";
import { computeNoteHash, computeBodyHash } from "./hash.js";

/**
 * Parse a single markdown file into a ParsedNote.
 *
 * `relativePath` is always posix (forward slashes), relative to `vaultRoot`.
 */
export async function parseNote(absolutePath: string, vaultRoot: string): Promise<ParsedNote> {
  const raw = await fs.readFile(absolutePath, "utf-8");
  const stat = await fs.stat(absolutePath);

  const parsed = matter(raw);
  const content = parsed.content;
  const fmData = parsed.data as Record<string, unknown> | undefined;
  const frontmatter: Record<string, unknown> | null =
    fmData !== undefined && Object.keys(fmData).length > 0 ? fmData : null;

  const title = extractTitle(content) ?? path.basename(absolutePath, ".md");
  const hash = computeNoteHash(content, frontmatter);
  const bodyHash = computeBodyHash(content);
  const mtime = Math.floor(stat.mtimeMs);
  // Body wikilinks first (richer data: line, alias), then frontmatter.
  // We deduplicate the frontmatter additions against the body set on the
  // (normalizedTarget, anchor) key — otherwise a member-list in frontmatter
  // that's also referenced in body would produce a "phantom" extra backlink.
  //
  // (Note: SQLite's UNIQUE(source, target, anchor) constraint does NOT dedup
  // here, because NULL anchors are never equal to each other under SQL
  // semantics. App-level dedup is the only reliable path.)
  //
  // Within body and within frontmatter we keep duplicates: body duplicates
  // are pre-existing behaviour (multiple mentions of the same target across
  // different lines were always inserted as separate rows), and frontmatter
  // duplicates are vanishingly rare in practice. Limiting the dedup scope
  // keeps this change minimal and behaviour-preserving for body wikilinks.
  const bodyLinks = extractWikilinks(content);
  const frontmatterLinks = extractFrontmatterWikilinks(frontmatter);
  const wikilinks =
    frontmatterLinks.length === 0
      ? bodyLinks
      : mergeFrontmatterIntoBody(bodyLinks, frontmatterLinks);
  const wordCount = countWords(content);
  const relativePath = toPosix(path.relative(path.resolve(vaultRoot), path.resolve(absolutePath)));

  return {
    relativePath,
    content,
    frontmatter,
    title,
    hash,
    bodyHash,
    mtime,
    wikilinks,
    wordCount,
  };
}

/**
 * Combine body and frontmatter wikilinks, dropping any frontmatter entry whose
 * `(normalizedTarget, anchor)` already appears in the body set. Both inputs
 * are preserved otherwise in their original order.
 */
function mergeFrontmatterIntoBody(
  body: ReturnType<typeof extractWikilinks>,
  fm: ReturnType<typeof extractFrontmatterWikilinks>,
): ReturnType<typeof extractWikilinks> {
  const seen = new Set<string>();
  for (const w of body) {
    seen.add(`${w.normalizedTarget}�${w.anchor ?? ""}`);
  }
  const result = body.slice();
  for (const w of fm) {
    const key = `${w.normalizedTarget}�${w.anchor ?? ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(w);
  }
  return result;
}

/** Find the first H1 (`# Title`) at the start of a line. */
function extractTitle(content: string): string | null {
  const lines = content.split("\n");
  for (const line of lines) {
    const m = /^#\s+(.+?)\s*$/.exec(line);
    if (m !== null && m[1] !== undefined) return m[1].trim();
    // Stop scanning into the body too far — but Obsidian title H1 can be
    // anywhere near the top. We keep scanning the whole content; cheap.
  }
  return null;
}

function countWords(content: string): number {
  if (content.length === 0) return 0;
  return content.split(/\s+/).filter((s) => s.length > 0).length;
}

function toPosix(p: string): string {
  return p.split(path.sep).join("/");
}
